// UC Motion Hover Core (UCMH) v1.0 — GSAP-only
// API:
//  - UCMH.config(opts)
//  - UCMH.register(selector, { prepare?, play, reset?, destroy? })
//  - UCMH.init(selector?)  // если селектор не указан — инициализирует все зарегистрированные
//  - UCMH.utils: getAtom, ensureWrapped, decideUnit, scheduleByLines, kill, bleed, etc.

(function(root){
  if(!root.gsap){ console.warn('[UCMH] GSAP not found'); return; }

  const G = root.gsap;

  const defaults = {
    // глобалки ядра
    hoverScope: 'self',              // 'self' | 'closest'
    hoverScopeSelector: '.t396__group',
    leaveMode: 'hold',               // 'hold' | 'reset'
    resetEase: 'power2.out',
    resetDuration: 0.18,             // сек
    forceUnhide: true,

    // типограф + сплит
    effect: 'letters',               // 'lines' | 'words' | 'letters'
    randomize: true,
    baseDelay: 0,                    // мс
    delayBetweenLines: 60,           // мс
    parallelLines: true,
    parallelLineStagger: 60,         // мс
    letterWordDelay: 12,             // мс

    // bleed как в reveal
    bleedK:   { top:0.20, right:0.20, bottom:0.14, left:0.10 },
    bleedMin: { top:8,    right:12,   bottom:6,    left:6    },
    italicWordPadK: 0.26
  };

  const state = {
    config: {...defaults},
    registry: new Map(),   // selector -> handler
    prepared: new WeakSet()
  };

  const $all = (sel, rootNode=document)=>Array.from(rootNode.querySelectorAll(sel));
  const getAtom = host => host?.classList?.contains('tn-atom') ? host : (host?.querySelector?.('.tn-atom') || host);

  function forceUnhide(atom, cfg){
    if(!cfg.forceUnhide) return;
    if(!atom) return;
    atom.style.visibility = 'visible';
    const cs = getComputedStyle(atom);
    if (cs.opacity === '0') atom.style.opacity = '1';
  }

  function splitPreservingHTML(atom, unit){
    if (!atom || atom.__ucmhSplitDone) return;
    const raw = atom.innerHTML;
    if (raw.includes('class="uc-line"') || raw.includes('class="uc-word"')) { atom.__ucmhSplitDone = true; return; }

    const parts = raw.replace(/(<\/?[^>]+>)/g,'|$1|').split('|');
    const out = [];
    for (const part of parts){
      if (!part) continue;
      if (part.startsWith('<')){ out.push(part); continue; }
      const tokens = part.replace(/&nbsp;/g,'\u00A0').split(/(\s)/g);
      for (const tok of tokens){
        if (tok==='') continue;
        if (/\s/.test(tok)) out.push('<span class="uc-space"> </span>');
        else {
          const safe = tok.replace(/\u00A0/g,'&nbsp;');
          if (unit==='letters'){
            const letters = safe.split('').map(ch=>`<span class="uc-letter">${ch}</span>`).join('');
            out.push(`<span class="uc-word">${letters}</span>`);
          } else out.push(`<span class="uc-word">${safe}</span>`);
        }
      }
    }
    atom.innerHTML = out.join('');
    atom.__ucmhSplitDone = true;
  }

  function groupByLines(atom){
    if (!atom || atom.querySelector('.uc-line')) return;
    const nodes = $all('.uc-word, .uc-space', atom);
    if(!nodes.length) return;

    const lines = [];
    let topRef = null, buf = [];
    nodes.forEach(n=>{
      const t = n.offsetTop;
      if (topRef===null || Math.abs(t-topRef)<=1){ topRef = (topRef??t); buf.push(n); }
      else { lines.push(buf); buf=[n]; topRef=t; }
    });
    if (buf.length) lines.push(buf);

    lines.forEach(arr=>{
      const w=document.createElement('div'); w.className='uc-line';
      const first=arr[0]; first.parentNode.insertBefore(w, first);
      arr.forEach(n=> w.appendChild(n));
    });
  }

  function applyBleed(atom, cfg){
    const cs = getComputedStyle(atom);
    const fs = parseFloat(cs.fontSize)||16;
    const pad = {
      top:    Math.max(cfg.bleedMin.top,    cfg.bleedK.top    * fs),
      right:  Math.max(cfg.bleedMin.right,  cfg.bleedK.right  * fs),
      bottom: Math.max(cfg.bleedMin.bottom, cfg.bleedK.bottom * fs),
      left:   Math.max(cfg.bleedMin.left,   cfg.bleedK.left   * fs),
    };
    $all('.uc-line', atom).forEach(line=>{
      line.style.overflow='visible';
      line.style.padding=`${pad.top}px ${pad.right}px ${pad.bottom}px ${pad.left}px`;
      line.style.margin=`${-pad.top}px ${-pad.right}px ${-pad.bottom}px ${-pad.left}px`;
    });
    $all('.uc-word', atom).forEach(word=>{
      const wcs = getComputedStyle(word);
      if (wcs.fontStyle==='italic'){
        const add = Math.ceil(cfg.italicWordPadK * fs);
        const cur = parseFloat(wcs.paddingRight)||0;
        word.style.paddingRight = (cur+add)+'px';
      }
    });
  }

  function ensureWrapped(atom, unit, cfg){
    splitPreservingHTML(atom, unit==='letters' ? 'letters' : 'words');
    groupByLines(atom);
    applyBleed(atom, cfg);
  }

  function decideUnit(cfg){ return cfg.effect || 'letters'; }

  function shuffle(arr){ for(let i=arr.length-1;i>0;i--){ const j=(Math.random()*(i+1))|0; [arr[i],arr[j]]=[arr[j],arr[i]]; } return arr; }

  // UCM.scheduleByLines аналог — отдаёт cb(itemsOrLine, whenMs)
  function scheduleByLines(atom, cfg, unit, cb){
    const lines = $all('.uc-line', atom);
    if(!lines.length) return;
    const {
      baseDelay, parallelLines, parallelLineStagger,
      delayBetweenLines, letterWordDelay, randomize
    } = cfg;

    if (parallelLines){
      lines.forEach((line, li)=>{
        const whenMs = baseDelay + li * parallelLineStagger;
        if (unit==='lines') cb(line, whenMs);
        else {
          const items = (unit==='letters') ? $all('.uc-letter', line) : $all('.uc-word, .uc-space', line);
          if (randomize) shuffle(items);
          cb(items, whenMs);
        }
      });
    } else {
      let acc = baseDelay;
      lines.forEach(line=>{
        if (unit==='lines'){
          cb(line, acc);
          const count = $all('.uc-word, .uc-space, .uc-letter', line).length||1;
          acc += count * letterWordDelay + delayBetweenLines;
        } else {
          const items = (unit==='letters') ? $all('.uc-letter', line) : $all('.uc-word, .uc-space', line);
          if (randomize) shuffle(items);
          cb(items, acc);
          acc += items.length * letterWordDelay + delayBetweenLines;
        }
      });
    }
  }

  function kill(targets){ G.killTweensOf(targets); }

  function bindHover(host, atom, handler, cfg){
    let scopeNode = (cfg.hoverScope==='closest' && cfg.hoverScopeSelector)
      ? host.closest(cfg.hoverScopeSelector) || atom
      : atom;

    const onEnter = ()=>{
      kill($all('.uc-word,.uc-space,.uc-letter', atom));
      // handler.play обязан построить свою анимацию / таймлайн и запустить
      handler.play(host, cfg, api);
    };

    const onLeave = ()=>{
      if (cfg.leaveMode==='reset'){
        const tgs = $all('.uc-word,.uc-space,.uc-letter', atom);
        G.to(tgs, {
          filter:'blur(0px)',
          opacity: '+=0',
          duration: cfg.resetDuration,
          ease: cfg.resetEase,
          onComplete: ()=> handler.reset && handler.reset(host, cfg, api)
        });
      } else {
        handler.reset && handler.reset(host, cfg, api); // опционально
      }
    };

    scopeNode.addEventListener('pointerenter', onEnter, {passive:true});
    scopeNode.addEventListener('pointerleave', onLeave, {passive:true});
    scopeNode.addEventListener('touchstart', onEnter, {passive:true});
  }

  // ===== публичный API ядра =====
  function config(opts){ Object.assign(state.config, opts||{}); }

  function register(selector, handler){
    state.registry.set(selector, handler);
  }

  function prepareHost(host, cfg, handler){
    if (state.prepared.has(host)) return;
    const atom = getAtom(host);
    if(!atom) return;

    forceUnhide(atom, cfg);
    const unit = decideUnit(cfg);
    ensureWrapped(atom, unit, cfg);
    // базовое видимое состояние
    $all('.uc-word,.uc-space,.uc-letter', atom).forEach(n=>{
      n.style.opacity='1'; n.style.filter='none'; n.style.willChange='';
    });

    handler.prepare && handler.prepare(host, cfg, api);
    bindHover(host, atom, handler, cfg);
    state.prepared.add(host);
  }

  function init(selector){
    const pairs = [];
    if (selector){
      // инициализируем конкретный селектор — ищем чей это handler
      const handler = state.registry.get(selector);
      if (handler){
        $all(selector).forEach(host=> pairs.push([host, handler]));
      }
    } else {
      // инициализируем все зарегистрированные селекторы
      state.registry.forEach((handler, sel)=>{
        $all(sel).forEach(host=> pairs.push([host, handler]));
      });
    }

    const cfg = {...state.config}; // снимок конфигурации на момент init
    pairs.forEach(([host, handler])=> prepareHost(host, cfg, handler));
  }

  const utils = { getAtom, ensureWrapped, decideUnit, scheduleByLines, kill, applyBleed, splitPreservingHTML, groupByLines };

  const api = { config, register, init, utils, _state: state };

  root.UCMH = api;

})(window);
